"""Phase 9: subgroup performance. Descriptive; small groups are flagged, and 'fair' is never declared."""
from _common import *
import joblib, numpy as np, pandas as pd
import matplotlib.pyplot as plt
from mhp.metrics import reg_metrics, bootstrap_ci
b = joblib.load(C.MODELS / "model_bundle.joblib"); conf = b["conformal"]
t = pd.read_csv(C.RESULTS / "test_predictions.csv", index_col="row_id")
top = b["reference"]["top_countries"]; t["Grouped_country"] = t.Country.where(t.Country.isin(top), "Other")
Xte = t[C.RAW_INPUTS]; sig = np.maximum(b["sigma_model"].predict(Xte), conf["eps"]); t["covered90"] = np.abs(t.y_true - t.pred_improved) <= conf["normalized_q"]["0.1"] * sig
rows = []
for col in C.SUBGROUP_COLS:
    for k, g in t.groupby(col):
        m = reg_metrics(g.y_true, g.pred_improved); mb = reg_metrics(g.y_true, g.pred_baseline); e = np.abs(g.y_true.values - g.pred_improved.values)
        ci = bootstrap_ci(lambda i: e[i].mean(), len(e), B=500) if len(e) >= 5 else (np.nan, np.nan)
        rows.append(dict(attribute=col, group=k, n=m["n"], MAE=m["MAE"], MAE_CI95_low=ci[0], MAE_CI95_high=ci[1], RMSE=m["RMSE"], R2=m["R2"], Bias=m["Bias"],
                         MAE_baseline=mb["MAE"], coverage90=g.covered90.mean(), sample_flag="LOW (n<30)" if m["n"] < 30 else ("limited (n<100)" if m["n"] < 100 else "ok")))
P = pd.DataFrame(rows); P.to_csv(C.RESULTS / "subgroup_performance.csv", index=False)
gaps = []
for col in C.SUBGROUP_COLS:
    d = P[(P.attribute == col) & (P.n >= 30)]
    if len(d) > 1: gaps.append(f"- **{col}**: MAE range {d.MAE.min():.3f} ({d.loc[d.MAE.idxmin(), 'group']}) to {d.MAE.max():.3f} ({d.loc[d.MAE.idxmax(), 'group']}); gap {d.MAE.max() - d.MAE.min():.3f} among groups with n>=30.")
md = ["# Subgroup / Fairness Analysis\n", "_Auto-generated by `scripts/09_fairness_subgroups.py` on the held-out test set (n=%d)._\n" % len(t),
      "## Results\n", P.round(3).to_markdown(index=False), "\n## Largest MAE gaps per attribute (groups with n>=30)\n", *gaps,
      "\n## How to read this (and what NOT to conclude)\n",
      "- These are **descriptive error rates**, not a fairness certification. The model is **not declared fair**; small gaps could hide larger ones because of low power, and large gaps in small groups may be noise (see CI columns).",
      "- Only two gender values (Male/Female) exist in the data; non-binary and other identities are **not represented**, so nothing can be said about them.",
      "- Age spans 18-24 only; academic level and country groups are imbalanced (see `n`). Country groups with n<30 are flagged LOW.",
      "- Equal error rates across groups is only one notion of fairness. Whether the dataset's score means the same thing across groups (measurement invariance) is NOT ESTABLISHED.",
      "- `Stress_Level` is not a demographic; it is included to show where the model is least accurate.",
      "- The baseline column (`MAE_baseline`) allows a like-for-like comparison against the original model per group."]
(C.DOCS if hasattr(C, "DOCS") else C.ROOT / "docs").joinpath("fairness.md").write_text("\n".join(md))
d = P[P.attribute.isin(["Gender", "Academic_Level", "Grouped_country"])]
fig, ax = plt.subplots(figsize=(8, 5)); lab = d.attribute.str[:8] + ": " + d.group.astype(str); yy = np.arange(len(d))[::-1]
ax.barh(yy, d.MAE, xerr=[d.MAE - d.MAE_CI95_low, d.MAE_CI95_high - d.MAE], color=["#C97C3B" if n < 30 else "#4C9A78" for n in d.n], alpha=.9)
ax.set_yticks(yy); ax.set_yticklabels([f"{l} (n={n})" for l, n in zip(lab, d.n)], fontsize=8); ax.axvline(t.eval("abs(y_true-pred_improved)").mean(), color="k", ls="--", lw=1)
ax.set_xlabel("test MAE with 95% bootstrap CI (orange: n<30)"); ax.set_title("Subgroup error"); fig.savefig(C.FIGURES / "subgroup_errors.png"); plt.close(fig)
print(P[["attribute", "group", "n", "MAE", "R2", "Bias", "coverage90", "sample_flag"]].round(3).to_string()); print("\n".join(gaps))
